use anyhow :: { Context , Result } ; use serde :: { Deserialize , Serialize } ; use std :: collections :: { HashMap , HashSet } ; use std :: fs ; use std :: path :: { Path , PathBuf } ; use std :: process :: Command ; use super :: * ; use tempfile :: NamedTempFile ; # [doc = " Generate SELinux .te policy file content"] pub fn generate_te_policy (services : & [ServiceAccess]) -> String { let mut lines = vec ! ["policy_module(zkperf_services, 1.0.0)" . to_string () , "" . to_string () , "require {" . to_string () , "    type unconfined_t;" . to_string () , "    type httpd_t;" . to_string () , "    type bin_t;" . to_string () , "    type usr_t;" . to_string () , "    type tmp_t;" . to_string () , "    type node_t;" . to_string () , "    class process { transition signal };" . to_string () , "    class file { read write getattr open create };" . to_string () , "    class dir { read search open };" . to_string () , "    class tcp_socket { create connect read write };" . to_string () , "    class udp_socket { create connect read write };" . to_string () , "}" . to_string () , "" . to_string () ,] ; let mut all_paths = HashSet :: new () ; for svc in services { all_paths . extend (svc . read_paths . iter () . cloned ()) ; all_paths . extend (svc . write_paths . iter () . cloned ()) ; all_paths . extend (svc . exec_paths . iter () . cloned ()) ; } for svc in services { let type_name = format ! ("{}_t" , svc . name . replace (['-' , '.'] , "_")) ; let exec_type = format ! ("{}_exec_t" , svc . name . replace (['-' , '.'] , "_")) ; lines . push (format ! ("type {}, user_domain_type, user_usertype;" , type_name)) ; lines . push (format ! ("type {};" , exec_type)) ; lines . push ("" . to_string ()) ; } for svc in services { let type_name = format ! ("{}_t" , svc . name . replace (['-' , '.'] , "_")) ; for path in & svc . read_paths { lines . push (format ! ("allow {} {}:file {{ read getattr open }};" , type_name , path)) ; } for path in & svc . write_paths { lines . push (format ! ("allow {} {}:file {{ write create }};" , type_name , path)) ; } if svc . needs_network { lines . push (format ! ("allow {} node_t:tcp_socket create;" , type_name)) ; lines . push (format ! ("allow {} node_t:udp_socket create;" , type_name)) ; } if svc . needs_tmp { lines . push (format ! ("allow {} tmp_t:file {{ read write create }};" , type_name)) ; } lines . push ("" . to_string ()) ; } lines . join ("\n") }